// GET /webhook/documents/verify?id=D00x: consultant marks an uploaded document as verified.
const config = configFrom('Config');
const id = String($('Consultant verifies').first().json.query?.id || '');
const doc = tableRows('Documents').find((d) => d.doc_id === id);
const temp = doc && tableRows('Temps').find((t) => t.temp_id === doc.temp_id);
const ok = doc && doc.status === 'received';
const notice = ok ? `Verified ${fullName(temp)}'s ${doc.doc_type}.` : 'Nothing to verify for that document.';
return [{ json: {
  updates: ok ? [{ id: doc.id, status: 'verified', verified_at: nowIso(), verified_by: config.consultant_name }] : [],
  location: `${config.base_url}/webhook/console?done=${encodeURIComponent(notice)}`,
} }];

// Shared helpers injected at the top of every Code node by scripts/build-workflows.mjs.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n) => '£' + Number(n || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const round2 = (n) => Math.round(Number(n || 0) * 100) / 100;
const newToken = () => require('crypto').randomBytes(18).toString('hex');
const nowIso = () => new Date().toISOString();
const fmtDate = (d) => (d ? new Date(d).toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }) : '');
// Every Code node runs right after "Load data", whose single item holds one array per data table.
const DATA = $input.first().json || {};
const tableRows = (table) => (Array.isArray(DATA[table]) ? DATA[table] : []);
const configFrom = () => Object.fromEntries(tableRows('Config').map((r) => [r.key, r.value]));
const fullName = (t) => (t ? `${t.first_name} ${t.last_name}` : '');

